package main

import (
	"flag"
	"fmt"
)

func listCmd(args []string) error {
	fs := flag.NewFlagSet("list", flag.ContinueOnError)
	all := fs.Bool("all", false, "include archived tasks")
	if err := fs.Parse(args); err != nil {
		return err
	}
	tasks, err := loadTasks()
	if err != nil {
		return err
	}
	for _, t := range tasks {
		if t.Archived && !*all {
			continue
		}
		fmt.Printf("%3d  %s\n", t.ID, t.Title)
	}
	return nil
}

